from dataclasses import dataclass

import pytest


@dataclass
class Rect:
    w: int
    h: int


@dataclass
class Square:
    side: int


@dataclass
class Tri:
    b: int
    h: int


Shape = Rect | Square | Tri


def area(s: Shape) -> int:
    """Area of the shape, rounded down. A triangle's area is b*h/2."""
    if isinstance(s, Rect):
        return s.w * s.h
    if isinstance(s, Square):
        return s.side * s.side
    return s.b * s.h // 2


def test_rect() -> None:
    assert area(Rect(3, 4)) == 12


def test_rect_zero_width() -> None:
    assert area(Rect(0, 7)) == 0


def test_square() -> None:
    assert area(Square(5)) == 25


def test_tri_even_product() -> None:
    assert area(Tri(4, 5)) == 10


def test_tri_odd_product_rounds_down() -> None:
    assert area(Tri(3, 5)) == 7


def test_tri_unit() -> None:
    assert area(Tri(1, 1)) == 0


def test_tri_zero_base() -> None:
    assert area(Tri(0, 9)) == 0


def test_shape_union_dispatch() -> None:
    shapes: list[Shape] = [Rect(2, 2), Square(3), Tri(6, 2)]
    assert [area(s) for s in shapes] == [4, 9, 6]
